```css
/* General Styles */
body {
    font-family: Arial, sans-serif;
    margin: 0;
    padding: 0;
    background-color: #1a1a1a; /* Dark background color */
    color: #fff; /* White text */
    line-height: 1.6;
}

.container {
    width: 80%;
    margin: 0 auto;
    padding: 20px;
}

/* Header Styles */
header {
    background-color: #222;
    padding: 10px 0;
    position: sticky; /* Keep the header at the top when scrolling  */
    top: 0;
    z-index: 100; /* ensures the header stays on top of content  */
}

header .container {
    display: flex;
    justify-content: space-between;
    align-items: center; /* Vertically center items */
}

.logo img {
    height: 50px; /* Adjust logo size */
}


nav ul {
    list-style: none;
    padding: 0;
    margin: 0;
    display: flex; /* Horizontal list */
}

nav li {
    margin-left: 20px;
}

nav a {
    color: #fff;
    text-decoration: none;
    padding: 5px 10px;
    border-radius: 5px; /* Rounded corners for links */
    transition: background-color 0.3s ease; /* Smooth hover effect */
}

nav a:hover {
    background-color: #333;
}

/* Hero Section */
.hero {
    background-color: #000000;  /* Darker background */
    padding: 50px 0;
    text-align: center;
}

.hero .container {
    display: flex; /* Use flexbox for layout */
    align-items: center; /* Vertically center content */
    justify-content: space-around; /* Space out content  */
}


.hero-content {
    width: 50%; /* Adjust width as needed */
    padding: 20px;
}

.hero-image img {
    max-width: 100%;  /* Image scales with its container */
    height: auto;
    border-radius: 10px; /* rounded corners */
}

.btn {
    display: inline-block;
    padding: 10px 20px;
    text-decoration: none;
    border-radius: 5px;
    transition: background-color 0.3s ease;
}

.primary-btn {
    background-color: #e51e24; /* CS:GO Red */
    color: #fff;
}

.secondary-btn {
    background-color: #333;
    color: #fff;
}


/* News Section */
.news-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); /* Responsive columns */
    gap: 20px;
}

.news-item {
    background-color: #333;
    padding: 20px;
    border-radius: 10px;
    text-align: left;
}

.news-item img {
    width: 100%;
    height: auto;
    margin-bottom: 10px;
    border-radius: 5px;
}

/* Maps, Weapons, Teams Sections (similar structure) */
.maps-grid, .weapons-grid, .teams-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(250px, 1fr)); /* Responsive columns */
    gap: 20px;
}

.map-card, .weapon-item, .team-item {
    background-color: #333;
    padding: 20px;
    border-radius: 10px;
    text-align: center;
}

.map-card img, .weapon-item img, .team-item img {
    width: 100%;
    max-height: 150px; /* Adjust as needed */
    object-fit: contain;  /* Prevent image distortion */
    margin-bottom: 10px;
    border-radius: 5px;
}

/* Community Section */
.community-content {
    text-align: center;
}

/* About Section */
.about {
    /* Add styling specific to the about section */
}

/* Footer Styles */
footer {
    background-color: #222;
    text-align: center;
    padding: 20px 0;
}


/*  Media Queries for responsiveness */
@media (max-width: 768px) {
    .container {
        width: 90%;
    }

    header .container {
        flex-direction: column; /* Stack header items vertically */
        align-items: center;
    }

    nav ul {
        margin-top: 10px;
    }

    .hero .container {
        flex-direction: column; /* Stack hero items vertically */
    }

    .hero-content, .hero-image {
        width: 90%;
        margin-bottom: 20px;
    }
}
```

